import { Host, h, Component, Prop, type ComponentInterface } from '@stencil/core';
import { useIcon } from '../runtime';

@Component({
  tag: 'ks-icon-more-horizontal',
  styleUrls: ['../styles/index.css'],
  shadow: true,
})
export class KsIconMoreHorizontal implements ComponentInterface {
  ['ks-icon-name']: string = 'ks-icon-more-horizontal';

  @Prop() size: string | number = 16;
  @Prop() color: string = 'currentColor';
  /**
   * @deprecated
   */
  @Prop() strokeWidth: string | number;
  /**
   * @deprecated
   */
  @Prop() absoluteStrokeWidth: boolean = false;

  render() {
    const icon = useIcon({ size: this.size, color: this.color });

    return (
      <Host class="ks-icon" ks-icon>
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width={icon.width}
          height={icon.height}
          viewBox="0 0 48 48"
          fill={icon.color}
        >
          <circle cx="24.011" cy="24" r="3"></circle>
          <circle cx="34.513" cy="24" r="3"></circle>
          <circle cx="13.509" cy="24" r="3"></circle>
        </svg>
      </Host>
    );
  }
}
